94:void CBillboardSceneNode::updateMesh(const irr::scene::ICameraSceneNode *camera)
95:{
96:	// billboard looks toward camera
97:	core::vector3df pos = getAbsolutePosition();
98:
99:	core::vector3df campos = camera->getAbsolutePosition();
100:	core::vector3df target = camera->getTarget();
101:	core::vector3df up = camera->getUpVector();
102:	core::vector3df view = target - campos;
103:	view.normalize();
104:
105:	core::vector3df horizontal = up.crossProduct(view);
106:	if (horizontal.getLength() == 0) {
107:		horizontal.set(up.Y, up.X, up.Z);
108:	}
109:	horizontal.normalize();
110:	core::vector3df topHorizontal = horizontal * 0.5f * TopEdgeWidth;
111:	horizontal *= 0.5f * Size.Width;
112:
113:	// pointing down!
114:	core::vector3df vertical = horizontal.crossProduct(view);
115:	vertical.normalize();
116:	vertical *= 0.5f * Size.Height;
117:
118:	view *= -1.0f;
119:
120:	auto &vertices = Buffer->Vertices->Data;
121:
122:	for (s32 i = 0; i < 4; ++i)
123:		vertices[i].Normal = view;
124:
125:	/* Vertices are:
126:	2--1
127:	|\ |
128:	| \|
129:	3--0
130:	*/
131:	vertices[0].Pos = pos + horizontal + vertical;
132:	vertices[1].Pos = pos + topHorizontal - vertical;
133:	vertices[2].Pos = pos - topHorizontal - vertical;
134:	vertices[3].Pos = pos - horizontal + vertical;
135:
136:	Buffer->setDirty(EBT_VERTEX);
137:	Buffer->recalculateBoundingBox();
138:}
